import { parse, postprocess, preprocess } from 'micromark';
import { frontmatter } from 'micromark-extension-frontmatter';
import { gfmTable } from 'micromark-extension-gfm-table';
const CODE_TYPES = new Set(['codeFenced', 'codeText', 'yaml', 'toml']);
const extensions = [
    frontmatter(['yaml', 'toml']),
    gfmTable(),
    { disable: { null: ['autolink', 'codeIndented', 'htmlFlow', 'htmlText'] } },
];
export const getCodeRanges = (content) => {
    const bom = content.startsWith('﻿') ? 1 : 0;
    const events = postprocess(parse({ extensions })
        .document()
        .write(preprocess()(content.slice(bom), undefined, true)));
    const ranges = [];
    for (const [kind, token] of events) {
        if (kind === 'enter' && CODE_TYPES.has(token.type)) {
            ranges.push([token.start.offset + bom, token.end.offset + bom]);
        }
    }
    return ranges;
};
